 horario, ¿qué significa «Abfahrt»?","options":["Salida","Llegada","Transbordo","Retraso"],"correct_index":0,"explanation":"Abfahrt significa salida de un medio de transporte.","source_url":"https://www.goethe.de/pro/relaunch/prf/de/A1_SD1_Wortliste_02.pdf","source_title":"Goethe-Institut · Vocabulario básico de alemán","reviewed_at":"2026-11-12","guide_path":null,"status":"published","editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["e14e98092a6b74e356120de7cd160f3c"]},{"question":{"id":"de-word-gleis","category":"idioma","difficulty":2,"scope":"CH","canton":null,"language":"de","prompt":"¿Qué indica «Gleis 4» en una estación?","options":["El andén 4","El vagón 4","La vía 4","El asiento 4"],"correct_index":2,"explanation":"Gleis designa la vía ferroviaria. En una estación ayuda a localizar desde dónde sale el tren.","source_url":"https://www.goethe.de/pro/relaunch/prf/de/A1_SD1_Wortliste_02.pdf","source_title":"Goethe-Institut · Vocabulario básico de alemán","reviewed_at":"2026-11-12","guide_path":null,"status":"published","editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["9fd1d87ef47423e244484083cb82af9e"]},{"question":{"id":"de-word-eingang","category":"idioma","difficulty":2,"scope":"CH","canton":null,"language":"de","prompt":"¿Qué señala un cartel con «Eingang»?","options":["El aseo","La caja","La entrada","La salida"],"correct_index":2,"explanation":"Eingang significa entrada; Ausgang es salida.","source_url":"https://www.goethe.de/pro/relaunch/prf/de/A1_SD1_Wortliste_02.pdf","source_title":"Goethe-Institut · Vocabulario básico de alemán","reviewed_at":"2026-11-12","guide_path":null,"status":"published"},"known":["462c489a8b444b790acf8e6e3eff45b3"]},{"question":{"id":"de-word-ausgang","category":"idioma","difficulty":2,"scope":"CH","canton":null,"language":"de","prompt":"¿Qué señala un cartel con «Ausgang»?","options":["La consulta","La salida"