isitos concretos dependen del permiso.","sources":[{"id":"zh-mobility-17","url":"https://www.zh.ch/de/migration-integration/willkommen/espanol/movilidad.html","title":"Kanton Zürich · Movilidad","authority":"Kanton Zürich","checked_at":"2026-11-17","locator":"Vehículos; bicicleta"}],"source_url":"https://www.zh.ch/de/migration-integration/willkommen/espanol/movilidad.html","source_title":"Kanton Zürich · Movilidad","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":true,"next_review_at":"2027-02-17","concept_id":"ZH:corto-permiso-meses","status":"published","editorial_difficulty":"facil","game_only":true,"correct_index":0,"editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["d96c6c6e377e94efc6be4a3fda8c3a41"]},{"question":{"id":"szx-zh-corto-registro-dias","collection":"suizamente-integration-1350-v1","territory":"ZH","scope":"canton","canton":"ZH","topic":"tramites","category":"administracion","difficulty":1,"language":"es","game_type":"choice","prompt":"Te mudas a un municipio de Zürich. Según la guía cantonal, ¿cuántos días tienes para inscribirte?","options":["14","8","30","60"],"explanation":"La guía fija catorce días para el empadronamiento. No hay que esperar a que venza ese plazo para informarse de los documentos necesarios.","sources":[{"id":"zh-arrival-17","url":"https://www.zh.ch/de/migration-integration/willkommen/espanol/instalarse.html","title":"Kanton Zürich · Instalarse","authority":"Kanton Zürich","checked_at":"2026-11-17","locator":"Empadronarse; seguro médico; asesoramiento"}],"source_url":"https://www.zh.ch/de/migration-integration/willkommen/espanol/instalarse.html","source_title":"Kanton Zürich · Instalarse","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":true,"next_review_at":"2027-02-17","concept_id":"ZH:corto-registro-dias","status":"published","editorial_difficulty":"f