-11-17","locator":"Paris in turmoil; monument"}],"source_url":"https://www.luzern.com/en/poi/lion-monument","source_title":"Luzern Tourismus · Lion Monument","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_review_at":"2027-11-17","concept_id":"LU:leon-roca","status":"published","editorial_difficulty":"facil","game_only":true,"correct_index":0},"known":["af8a792033995c7337c7be5f06aaea3d"]},{"question":{"id":"szx-lu-fasnacht-navidad","collection":"suizamente-integration-1350-v1","territory":"LU","scope":"canton","canton":"LU","topic":"cultura","category":"sociedad","difficulty":1,"language":"es","game_type":"tf","prompt":"La Fasnacht de Luzern se celebra después de Semana Santa.","options":["Verdadero","Falso"],"explanation":"Fasnacht es el carnaval que precede a la Cuaresma. Las fechas cambian cada año.","sources":[{"id":"lu-carnival-17","url":"https://www.luzern.com/en/highlights/carnival-in-lucerne/All","title":"Luzern Tourismus · Carnival","authority":"Luzern Tourismus","checked_at":"2026-11-17","locator":"Calendar; Urknall; parades; bridge pictures"},{"id":"lu-portrait-17","url":"https://gruezi.lu.ch/kanton_luzern/kurzportrait","title":"Kanton Luzern · Kurzportrait","authority":"Kanton Luzern","checked_at":"2026-11-17","locator":"Brauchtum und Tradition"}],"source_url":"https://www.luzern.com/en/highlights/carnival-in-lucerne/All","source_title":"Luzern Tourismus · Carnival","reviewed_at":"2026-11-17","verified_at":"2026-11-17","validation_status":"verified","needs_periodic_review":false,"next_review_at":"2027-11-17","concept_id":"LU:fasnacht-navidad","status":"published","editorial_difficulty":"facil","game_only":true,"correct_index":1,"editorial_review":{"date":"2026-11-18","revision":"complete-14","kind":"wording-and-interaction"}},"known":["7052eaf3269483facddf762b3b63c7df"]},{"question":{"id":"szx-lu-entlebuch-solo-nieve","collection":"suizamente-integration-1350-v1","territory":"LU","s